        parsed = parse_version(v)
        major, minor, patch, prerelease_ids = parsed

        # Create tuple for sorting
        # (major, minor, patch, prerelease_tuple)
        # For prerelease: we need to make sure None sorts after any pre-release
        if prerelease_ids is None:
            # No pre-release: sorts after pre-release versions
            prerelease_tuple = (1,)  # Use 1 to sort after 0
